const families = {
  travel: '移动调度',
  roads: '路况工程',
  estate: '地产经营',
  funds: '资金往来',
  ward: '防御反制',
  status: '持续状态',
};
const targetNames = {
  self: '本人',
  steps: '指定步数',
  street: '道路地块',
  fork: '岔口出口',
  mark: '现有路标',
  own: '己方地产',
  vacant: '空置地产',
  rivalLot: '对手地产',
  person: '对手',
  negative: '本人或对手',
  all: '全场',
};
const shop = '商店／机遇补给',
  event = '机遇补给',
  craft = '材料合成';
function c(id, name, group, aim, radius, price, description, duration, stack, clear, source) {
  return {
    id,
    name,
    group,
    category: families[group],
    aim,
    target: targetNames[aim],
    radius,
    range: radius
      ? '沿路网 ' + radius + ' 格以内'
      : aim === 'steps'
        ? '可达终点见棋盘'
        : aim === 'self'
          ? '自身'
          : '全图',
    icon: id,
    price,
    description,
    timing: '本人掷骰前，每回合限用一张',
    duration,
    stack,
    clear,
    source: source ?? (price ? shop : event),
  };
}
